// 税込金額を計算して返す（端数切り捨て）
function calcTax(price, rate) {
  if (typeof price !== 'number') throw new Error('priceは数値で指定してください');
  return Math.floor(price * (1 + rate));
}

// 日付を指定書式の文字列にして返す。fmtは 'YYYY/MM/DD' など
function formatDate(date, fmt) {
  const d = new Date(date);
  const p = (n) => String(n).padStart(2, '0');
  return fmt.replace('YYYY', d.getFullYear()).replace('MM', p(d.getMonth() + 1)).replace('DD', p(d.getDate()));
}

// 郵便番号から住所を非同期で取得して返す
async function lookupAddress(zip) {
  const res = await vja.fetch('https://zipcloud.ibsnet.co.jp/api/search?zipcode=' + zip);
  const json = await res.json();
  return json.results ? json.results[0].address1 + json.results[0].address2 + json.results[0].address3 : null;
}
